#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    // Define a regex pattern to match markdown syntax
    std::regex pattern(R"(
        ^(.*?)$
    )");

    // Create a match object to hold the matched text
